#!/usr/bin/env node
/**
 * Synchronize each package's src/version.ts with package metadata.
 *
 * Run via `pnpm sync:versions`. CI checks drift via `pnpm sync:versions:check`.
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HEADER =
  '// Auto-generated by scripts/sync-package-versions.mjs.\n' +
  '// Do not edit by hand. Run `pnpm sync:versions` to refresh.\n';
const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const packagesDir = join(repoRoot, 'packages');

function quoteTypeScriptString(value) {
  return `'${String(value).replaceAll('\\', '\\\\').replaceAll("'", "\\'")}'`;
}

export function renderVersionModule(metadata) {
  return (
    HEADER +
    `export const SDK_NAME = ${quoteTypeScriptString(metadata.name)};\n` +
    `export const SDK_VERSION = ${quoteTypeScriptString(metadata.version)};\n`
  );
}

export function synchronizePackageVersions({ write }) {
  const stalePackages = [];
  let packageCount = 0;

  for (const slug of readdirSync(packagesDir).sort()) {
    const packageRoot = join(packagesDir, slug);
    const packageJsonPath = join(packageRoot, 'package.json');
    if (!existsSync(packageJsonPath)) continue;

    const metadata = JSON.parse(readFileSync(packageJsonPath, 'utf8'));
    if (metadata.private === true || !metadata.name || !metadata.version) continue;
    packageCount += 1;

    const target = join(packageRoot, 'src/version.ts');
    const existing = existsSync(target) ? readFileSync(target, 'utf8') : undefined;
    const expected = renderVersionModule(metadata);
    if (existing === expected) continue;

    stalePackages.push(slug);
    if (write) {
      mkdirSync(dirname(target), { recursive: true });
      writeFileSync(target, expected);
    }
  }

  return {
    packageCount,
    stalePackages,
  };
}

function runCli() {
  const checkOnly = process.argv.includes('--check');
  const { packageCount, stalePackages } = synchronizePackageVersions({ write: !checkOnly });

  if (checkOnly && stalePackages.length > 0) {
    console.error(`Generated version modules are out of sync: ${stalePackages.join(', ')}`);
    console.error('Run `pnpm sync:versions` and commit the result.');
    process.exitCode = 1;
    return;
  }

  const action = checkOnly ? 'Checked' : 'Synchronized';
  console.log(
    `${action} ${packageCount} version modules; ${stalePackages.length} module(s) ${checkOnly ? 'need updates' : 'updated'}.`,
  );
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runCli();
}
